+        }
+        if (haveCreatedCycle) {
+            patternBankMap.put("FOO-" + (nodeCount - 1), "foo");
+        } else {
+            // We didn't randomly create a cycle, so just force one in this last pattern
+            nodeToHaveCycle = nodeCount - 1;
+            patternBankMap.put("FOO-" + nodeToHaveCycle, "%{FOO-" + nodeToHaveCycle + "}");
+        }
