+            doc.add(new XYPointField(FIELD_NAME, (float) point.getX(), (float) point.getY()));
+            doc.add(new XYDocValuesField(FIELD_NAME, (float) point.getX(), (float) point.getY()));
+            w.addDocument(doc);
