+    @Override
+    public String getName() {
+        return NAME;
+    }
+
+    private boolean sourceShouldRewrite(QueryRewriteContext ctx) throws IOException {
+        for (var source : sources) {
+            if (source.isCompound()) {
+                return true;
+            }
+            var newSource = source.rewrite(ctx);
+            if (newSource != source) {
+                return true;
+            }
+        }
+        return false;
+    }
