+        for (var retriever : sources) {
+            var query = retriever.topDocsQuery();
+            if (query != null) {
+                if (retriever.retrieverName() != null) {
+                    query.queryName(retriever.retrieverName());
+                }
+                disMax.add(query);
+            }
+        }
