+        } else {
+            return allocation.decision(
+                Decision.NO,
+                NAME,
+                "max supported index version [%s] is older than the snapshot version [%s]",
+                target.node().getMaxIndexVersion().toReleaseVersion(),
+                recoverySource.version().toReleaseVersion()
+            );
+        }
+    }
