+                        () -> Strings.format(
+                            "[%s] failed verifying metadata integrity for index generation [%d]: repo UUID [%s], cluster UUID [%s]",
+                            repositoryName,
+                            repositoryData.getGenId(),
+                            repositoryData.getUuid(),
+                            repositoryData.getClusterUUID()
